import React from "react";

const HomePage = () => {
  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center">
      {/* Navigation Bar */}
      <nav className="w-full bg-blue-600 p-4 text-white flex justify-between">
        <h1 className="text-2xl font-bold">SRC E-Voting System</h1>
        <div>
          <button className="bg-white text-blue-600 px-4 py-2 rounded mr-2">Login</button>
          <button className="bg-green-500 text-white px-4 py-2 rounded">Sign Up</button>
        </div>
      </nav>

      {/* Hero Section */}
      <div className="flex flex-col items-center justify-center flex-grow text-center p-6">
        <h2 className="text-4xl font-bold text-gray-800">Your Vote, Your Voice!</h2>
        <p className="mt-4 text-lg text-gray-600 max-w-2xl">
          Participate in the SRC elections securely and fairly using our online e-voting system.
          View candidate manifestos, cast your vote, and see results in real-time.
        </p>
        <button className="mt-6 bg-blue-600 text-white px-6 py-3 rounded text-lg">
          Get Started
        </button>
      </div>

      {/* Election Details Section */}
      <div className="w-full bg-white shadow-md p-6 text-center">
        <h3 className="text-xl font-semibold text-gray-700">Upcoming Elections</h3>
        <p className="text-gray-600">Voting opens on: <strong>March 15, 2025</strong></p>
        <p className="text-gray-600">Voting closes on: <strong>March 16, 2025</strong></p>
      </div>
    </div>
  );
};

export default HomePage;
